import { describe, it } from "vitest";

// Reading adopted for failures: the domain throws an Error; the CLI turns it into
// a non-zero exit status with an error description on stderr and nothing on stdout.
// Premiums below include the 10 % first-insurance surcharge (each quoted item is a
// first insurance) and the 5 G fee; "base" values from the spec are noted alongside.

describe("quote — base premiums (newcomer, first contract)", () => {
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("plain sword → 115 G (base 100 + 10 first insurance + 5 fee)");
  it.todo("plain amulet → 71 G (base 60 + 6 + 5)");
  it.todo("plain staff → 93 G (base 80 + 8 + 5)");
  it.todo("plain potion → 49 G (base 40 + 4 + 5)");
  it.todo("1 rune → 33 G (base 25 + 2.5 + 5 = 32.5, rounded up)");
  it.todo("1 moonstone → 33 G (base 25, same as rune)");
  it.todo("2 runes → 60 G (base 50)");
  it.todo("3 runes → 71 G (base 60, block applies)");
  it.todo("4 runes → 115 G (base 100, no block — block requires exactly 3)");
  it.todo("7 runes → 198 G (base 175; 197.5 rounded up in MHPCO's favor)");
  it.todo("2 runes + 1 moonstone → 88 G (base 75, no block: different types; 87.5 rounded up)");
  it.todo("3 runes + 3 moonstones → 137 G (base 120, two separate blocks)");
  it.todo("unknown item type (broomstick) → throws an Error");
});

describe("quote — item-specific modifiers", () => {
  it.todo("cursed sword, enchantment 3, newcomer → 165 G (100 + 50 curse + 10 first + 5)");
  it.todo("sword with exactly enchantment 5 → 145 G (100 + 30 high enchantment + 10 + 5)");
  it.todo("cursed sword with exactly enchantment 5 → 195 G (both surcharges)");
  it.todo("sword with enchantment 4 → 115 G (no high-enchantment surcharge)");
  it.todo("cursed sword with enchantment 4 → 165 G (curse surcharge only)");
  it.todo("cursed potion → 69 G (40 + 20 curse + 4 + 5) — surcharges apply to non-sword items");
  it.todo("amulet with enchantment 6 → 89 G (60 + 18 high enchantment + 6 + 5)");
  it.todo("cursed sword + plain amulet → 231 G (base 160 + 50 curse on sword only + 16 first + 5)");
});

describe("quote — policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years, plain sword → 95 G (100 − 20 loyalty + 10 + 5)");
  it.todo("customer with 1 year, plain sword → 115 G (no loyalty discount)");
  it.todo("second quote of a 0-year customer, plain sword → 100 G (100 + 10 − 15 follow-up + 5)");
  it.todo("third quote of a 0-year customer, plain sword → 100 G (15 % on each follow-up contract)");
  it.todo("3-year customer, second quote, cursed sword enchantment 7 → 160 G (integration example)");
});

describe("claim — reimbursement", () => {
  it.todo("schema example: 5-year customer, silver amulet ench 2 → premium 59 G; fire damage 200 → payout 100, remainingCap 1100");
  it.todo("steel sword ench 3, damage 500 → payout 400, remainingCap 1600");
  it.todo("rune, damage 200 → payout 100, remainingCap 400");
  it.todo("moonstone, damage 200 → payout 100, remainingCap 400");
  it.todo("staff, damage 300 → payout 200, remainingCap 1400");
  it.todo("potion, damage 300 → payout 200, remainingCap 600");
  it.todo("steel sword ench 9, damage 1000 → payout 400 (50 % then deductible)");
  it.todo("dragon sword ench 9, damage 1000 → payout 400 (50 % rule wins)");
  it.todo("dragon sword exactly ench 8, damage 1000 → payout 400");
  it.todo("dragon sword ench 5, damage 800 → payout 700 (full reimbursement minus deductible)");
  it.todo("steel sword ench 8, damage 901 → payout 350 (350.5 rounded down)");
  it.todo("sword 500 + amulet 300 in one incident → payout 600 (deductible per damaged item), remainingCap 2600");
  it.todo("two swords insured, both damaged 500 → payout 800, remainingCap 3200 (cap 4000)");
});

describe("claim — cap", () => {
  it.todo("cursed sword policy, damage 500 → remainingCap 1600 (cap 2000 from insurance value, not premium)");
  it.todo("sword + 3 runes policy, sword damage 500 → remainingCap 3100 (insurance sum 1750)");
  it.todo("sword policy, two successive claims of 1500 → payouts 1400 then 600; remainingCap 600 then 0");
});

describe("claim — rejections", () => {
  it.todo("damage to an amulet when only a sword is insured → throws an Error");
  it.todo("damage to an unknown item type → throws an Error");
  it.todo("two sword damages but only one sword insured → throws an Error");
  it.todo("damage amount −200 → throws an Error");
});

