import { premiumFor, type Customer, type InsuredItem } from "./premium.js";

export type { Customer, InsuredItem };

export interface QuoteStep {
  op: "quote";
  items: InsuredItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

interface Policy {
  items: InsuredItem[];
  remainingCap: number;
}

const INSURANCE_VALUES: Record<string, number> = {
  amulet: 600,
};
const CAP_MULTIPLIER = 2;
const DEDUCTIBLE = 100;

function openPolicy(items: InsuredItem[]): Policy {
  const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
  return { items, remainingCap: CAP_MULTIPLIER * insuranceSum };
}

function claim(step: ClaimStep, policy: Policy): ClaimResult {
  const payout = step.incident.damages.reduce((sum, damage) => sum + damage.amount - DEDUCTIBLE, 0);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") {
      return claim(step, policies.get(step.policy) as Policy);
    }
    policies.set(index, openPolicy(step.items));
    return { premium: premiumFor(step.items, scenario.customer, index) };
  });
  return { results };
}
EOF
